        { "townMap", "Quests on Minimap", "Shows the quest givers and objectives near you on the minimap too.", "Map Pins", "Quests", false },
        { "townMap", "Minimap Quest Pin Size", "How big the quest pins are on the minimap.", "Map Pins", "Quests", false },
        { "townMap", "Hidden Quests", "Puts the quests you hid with a right-click back on the map.", "Map Pins", "Quests", false },
        { "townMap", "Rares", "A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown.", "Map Pins", "Rares", false },
        { "townMap", "Show Killed Rares", "Also a grey star on the map for the rares you have killed.", "Map Pins", "Rares", false },
        { "townMap", "Rare Pin Size", "How big the stars are on the map.", "Map Pins", "Rares", false },
        { "townMap", "Gathered Herbs and Ore", "Every herb and vein you gather, on the world map; click one for a waypoint.", "Map Pins", "Glimmer", false },
        { "townMap", "Gathered Pin Size", "How big the pins are on the map.", "Map Pins", "Glimmer", false },
    },
    ["QoL/Combat"] = {
        { "stealthReminder", false, "Out-of-combat stealth status for rogues and druids: a reminder while you are not in stealth. Move it in the HUD Editor.", "Stealth Reminder", false, false },
