    ["QoL/Questing & Group"] = {
        { "quests", false, "Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says.", "Quests", false, false },
        { "quests", "Accept Quests", "Accepts a quest as soon as its text opens. Use the Modifier to read it first.", "Quests", false, false },
        { "quests", "Hand In Quests", "Hands in finished quests. A quest with a choice of rewards waits for you to pick one, unless you saved a reward for it. The Modifier skips it for that quest.", "Quests", false, false },
        { "quests", "Pick Quests From NPCs", "When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above.", "Quests", false, false },
        { "quests", "Skip Grey Quests", "Accept Quests and Pick Quests From NPCs leave grey quests for you to take by hand.", "Quests", false, false },
        { "quests", "Saved Quest Rewards", "Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest on this class; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you.", "Quests", false, false },
        { "quests", "Share Quests With Group", "While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself.", "Quests", false, false },
        { "quests", "Modifier", "The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing.", "Quests", false, false },
        { "quests", "Modifier Does", "Skips: the quest steps run unless you hold the key. Triggers: they run only while you hold it.", "Quests", false, false },
        { "Open Saved Rewards", false, "Saved Quest Rewards Every reward this class saved for a quest, to look over and remove.", "Open Saved Rewards", false, false },
        { "questProgress", false, "Says your quest objective progress in party chat.", "Announce Quest Progress", false, false },
        { "questProgress", "Only Finished Objectives", "Says an objective once it is done, not every kill or item on the way.", "Announce Quest Progress", false, false },
        { "questLinkLevels", false, "Shows each quest's level on the quest links people say in chat.", "Quest Levels in Chat", false, false },
        { "gossip", false, "Picks the only option of a vendor, trainer, banker, auctioneer, stable master or flight master; nothing that costs money or moves you.", "NPC Gossip", false, false },
        { "gossip", "Modifier", "The key that changes Auto Gossip for that NPC.", "NPC Gossip", false, false },
        { "gossip", "Modifier Does", "Skips: it picks unless you hold the key. Triggers: it picks only while you hold it.", "NPC Gossip", false, false },
        { "groupButtons", false, "Invite, Disband and an invite button per friend, on your screen.", "On-Screen Buttons", false, false },
        { "groupButtons", "Growth Direction", "Which way the buttons line up from the first one.", "On-Screen Buttons", false, false },
        { "groupButtons", "Invite Buttons", "Pick the friends who get their own invite button.", "On-Screen Buttons", false, false },
        { "groupButtons", "Invite Target Button", "A button that invites your target.", "On-Screen Buttons", false, false },
        { "groupButtons", "Invite All Button", "A button that invites everyone on your invite buttons.", "On-Screen Buttons", false, false },
        { "groupButtons", "Disband Group", "Removes everyone from your group. Group leader only.", "On-Screen Buttons", false, false },
        { "groupButtons", "Button Width", false, "On-Screen Buttons", "Size", false },
        { "groupButtons", "Button Height", false, "On-Screen Buttons", "Size", false },
        { "groupButtons", "Font", false, "On-Screen Buttons", "Text", false },
        { "groupButtons", "Font Size", false, "On-Screen Buttons", "Text", false },
        { "groupButtons", "Outline", "A black outline round the text, in place of the soft shadow.", "On-Screen Buttons", "Text", false },
        { "groupButtons", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "On-Screen Buttons", "Background", false },
        { "freeForAll", false, "Sets your party's loot to Free for All whenever you lead it.", "Always Free for All", false, false },
        { "layerSwap", false, "Accepts the layer swap prompt when you join a group.", "Auto-Accept Layer Swap", false, false },
        { "layerTracker", false, "Shows which layer you are on, read from the NPCs around you.", "Layer Tracker", false, false },
        { "layerTracker", "Countdown to a Layer Change", "Counts down on the line when the game is about to move you to another layer.", "Layer Tracker", "Show", false },
        { "layerTracker", "Say When You Move", "A line in chat with your new layer after the game moves you.", "Layer Tracker", "Show", false },
        { "layerTracker", "Swap Layers With Others", "Click the line to ask players on other layers of your zone for an invite.", "Layer Tracker", "Swaps", false },
        { "layerTracker", "Show Requests From Others", "Asks whether to invite a player in your zone who wants your layer.", "Layer Tracker", "Swaps", false },
        { "layerTracker", "Leave Failed Swaps", "Leaves the group again when joining it did not move you.", "Layer Tracker", "Swaps", false },
        { "layerTracker", "Font", false, "Layer Tracker", "Text", false },
        { "layerTracker", "Font Size", false, "Layer Tracker", "Text", false },
        { "layerTracker", "Outline", "A black outline round the text, in place of the soft shadow.", "Layer Tracker", "Text", false },
        { "layerTracker", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Layer Tracker", "Background", false },
        { "playerHistory", false, "Remembers the players you group and chat with, stored only on your computer. Remembers the players you group and chat with, stored only on your computer. inspect panel history tab player tab notes", "Player History", false, "inspect panel history tab player tab notes" },
        { "playerHistory", "Record Chats", "Also keeps your last whispers and group chat lines with each player.", "Player History", false, false },
        { "playerHistory", "Forget After", "Forgets players you have not met for this many days.", "Player History", false, false },
        { "playerHistory", "Notes on Tooltips", "Shows your note and tag on a player's tooltip.", "Player History", false, false },
        { "playerHistory", "Clear History", "Deletes every player's recorded history, keeping your notes.", "Player History", false, false },
        { "playerHistory", "Clear Notes", "Deletes every note and tag you wrote on a player.", "Player History", false, false },
        { "finderRoles", false, "Role buttons on the Group Finder that show only the players and groups you want.", "Group Finder Roles", false, false },
    },
    ["QoL/XP"] = {
        { "xpBar", false, "Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour.", "XP Bar", false, false },
        { "xpBar", "Show at Max Level", "Keeps the bar up at max level, with your played time and session.", "XP Bar", "Show", false },
        { "xpBar", "Keep Blizzard XP Bar", "Leaves Blizzard's experience bar up as well, so your action bars keep their spacing.", "XP Bar", "Show", false },
        { "xpBar", "Show Texts On Mouseover", "Hides the texts until you hover the bar: the ones around it, or those on it too.", "XP Bar", "Show", false },
        { "xpBar", "Incomplete Quests", "The XP of quests still in progress, as a faded segment after the completed ones.", "XP Bar", "Show", false },
        { "xpBar", "Reset Session on Reload", "Starts the session time and XP/Hour again on a /reload. Off: a /reload carries on the session. A fresh login always starts a new one.", "XP Bar", "Show", false },
        { "xpBar", "Width", false, "XP Bar", "Bar", false },
        { "xpBar", "Height", false, "XP Bar", "Bar", false },
        { "xpBar", "Bar Texture", false, "XP Bar", "Bar", false },
        { "xpBar", "Background Opacity", false, "XP Bar", "Bar", false },
        { "xpBar", "Shine", "A soft shine along the top of the bar and a glow where your XP ends.", "XP Bar", "Effects", false },
        { "xpBar", "Notches", "Slim marks along the bottom of the bar at every 10%.", "XP Bar", "Effects", false },
        { "xpBar", "Rested Stripes", "Fine diagonal stripes on the rested band.", "XP Bar", "Effects", false },
        { "xpBar", "Quest XP Pulse", "The XP from a quest you hand in flashes on the bar and its amount rises off it.", "XP Bar", "Effects", false },
        { "xpBar", "Ready to Level", "Your completed quests glow, with a star on the bar, when handing them in would level you.", "XP Bar", "Effects", false },
        { "xpBar", "Level-Up Flash", "The bar flashes gold and drains back to empty when you level up.", "XP Bar", "Effects", false },
        { "xpBar", "Hover Breakdown", "Hovering the bar shows your XP to level, quest and rested XP, and about how many kills are left.", "XP Bar", "Effects", false },
        { "xpBar", "Font", false, "XP Bar", "Text", false },
        { "xpBar", "Font Size", false, "XP Bar", "Text", false },
        { "xpBar", "Outline", "A black outline round the text, in place of the soft shadow.", "XP Bar", "Text", false },
        { "xpBar", "Fill Color", "Your experience. Its left end is a darker shade.", "XP Bar", "Colors", false },
        { "xpBar", "Completed Quests Color", "The XP of completed quests, and their text.", "XP Bar", "Colors", false },
        { "xpBar", "Incomplete Quests Color", "The XP of quests still in progress. By default the completed quests color, faded.", "XP Bar", "Colors", false },
        { "xpBar", "Rested Color", "Rested experience, and its text.", "XP Bar", "Colors", false },
        { "xpBar", "Background Color", "Behind the fill.", "XP Bar", "Colors", false },
        { "xpBar", "Border Color", "The line round the bar.", "XP Bar", "Colors", false },
        { "xpBar", "Left Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text", false },
        { "xpBar", "Center Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text", false },
        { "xpBar", "Right Text", "A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there.", "XP Bar", "Text", false },
        { "xpBar", "Top Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Top", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Top Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Bottom Left", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Bottom", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpBar", "Bottom Right", "A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level.", "XP Bar", "Around the Bar", false },
        { "xpTicker", false, "Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor.", "XP per Hour", false, false },
        { "xpTicker", "Show Played Time", "Your total played time on this character, from level 1.", "XP per Hour", "Shown", false },
        { "xpTicker", "Compare Characters", "Shows if you're ahead of or behind your other characters, and colors past levels by it.", "XP per Hour", "Shown", false },
        { "xpTicker", "Show Ding Time", "How long the next level takes at your current rate.", "XP per Hour", "Shown", false },
        { "xpTicker", "Show Time", "How long this session has run.", "XP per Hour", "Shown", false },
        { "xpTicker", "Reset XP per Hour", "Starts the session again: its time, XP and rate. The XP Bar's XP/Hour starts again with it.", "XP per Hour", "Shown", false },
        { "xpTicker", "Level History", "The level you are on as it runs, then completed levels, newest first.", "XP per Hour", "Level History", false },
        { "xpTicker", "Levels Shown", "The most recent completed levels.", "XP per Hour", "Level History", false },
        { "xpTicker", "Show Played at Ding", "Your played time when you reached each level, beside how long it took.", "XP per Hour", "Level History", false },
        { "xpTicker", "Font", false, "XP per Hour", "Text", false },
        { "xpTicker", "Font Size", false, "XP per Hour", "Text", false },
        { "xpTicker", "Outline", "A black outline round the text, in place of the soft shadow.", "XP per Hour", "Text", false },
        { "xpTicker", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "XP per Hour", "Background", false },
        { "xpTicker", "Hide While Resting", "Hidden in cities and inns.", "XP per Hour", "Visibility", false },
        { "groupXP", false, "A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor.", "Group XP", false, false },
        { "groupXP", "Show Yourself", "Your own bar among the group's.", "Group XP", false, false },
        { "groupXP", "Show in Raids", "Also shows the bars while you are in a raid.", "Group XP", false, false },
        { "groupXP", "Width", false, "Group XP", "Size", false },
        { "groupXP", "Font", false, "Group XP", "Text", false },
        { "groupXP", "Font Size", false, "Group XP", "Text", false },
        { "groupXP", "Outline", "A black outline round the text, in place of the soft shadow.", "Group XP", "Text", false },
        { "groupXP", "Bar Texture", false, "Group XP", "Bar", false },
        { "groupXP", "Background Opacity", false, "Group XP", "Bar", false },
        { "talentPoints", false, "Text on screen while you have talent points to spend. Hidden in combat. Move it in the HUD Editor.", "Talent Points", false, false },
        { "talentPoints", "Font", false, "Talent Points", "Text", false },
        { "talentPoints", "Font Size", false, "Talent Points", "Text", false },
        { "talentPoints", "Outline", "A black outline round the text, in place of the soft shadow.", "Talent Points", "Text", false },
        { "talentPoints", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Talent Points", "Background", false },
        { "talentPoints", "Apply Theme to Text Color", "The text in the theme's accent color instead of gold.", "Talent Points", "Colors", false },
        { "legacyPoints", false, "Shows your unspent Legacy points outside combat.", "Unspent Legacy Points", false, false },
        { "legacyPoints", "Font", false, "Unspent Legacy Points", "Text", false },
        { "legacyPoints", "Font Size", false, "Unspent Legacy Points", "Text", false },
        { "legacyPoints", "Outline", "A black outline round the text, in place of the soft shadow.", "Unspent Legacy Points", "Text", false },
        { "legacyPoints", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Unspent Legacy Points", "Background", false },
        { "legacyPoints", "Apply Theme to Text Color", "The text in the theme's accent color instead of gold.", "Unspent Legacy Points", "Colors", false },
        { "trainer", false, "After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars.", "Trainer Popup", false, false },
        { "trainer", "Glow New Abilities", "Lights up the new abilities on your action bars until you use them.", "Trainer Popup", false, false },
        { "trainer", "Offer to Replace Lower Ranks", "Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat.", "Trainer Popup", false, false },
        { "trainer", "Check My Bars Now", "Looks for lower ranks on your bars now, as after a trainer visit (also /naowh ranks). Out of combat only.", "Trainer Popup", false, false },
        { "trainer", "Forget Kept Spells", "Forgets the spells you chose to keep at lower ranks, so the popup offers to swap them again.", "Trainer Popup", false, false },
        { "trainer", "Popup Position", "Puts the popup back where it first showed.", "Trainer Popup", false, false },
    },
    ["QoL/Loot & Items"] = {
        { "lootFeed", false, "Everything you loot pops up on screen with its icon, amount and value, stacking in your chosen direction and fading out. Hover a line for the item's tooltip. Move it in the HUD Editor.", "Loot Feed", false, false },
        { "lootFeed", "Show Money", false, "Loot Feed", "Lines", false },
        { "lootFeed", "Show Quest Rewards", "A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines.", "Loot Feed", "Lines", false },
        { "lootFeed", "Show Reputation", "A line for every reputation gain, from quests and kills alike.", "Loot Feed", "Lines", false },
        { "lootFeed", "Show Kill Experience", "A line for the experience from each kill. Quest experience is on the quest's own line.", "Loot Feed", "Lines", false },
        { "lootFeed", "Lowest Quality Shown", false, "Loot Feed", "Lines", false },
        { "lootFeed", "Lines Shown", false, "Loot Feed", "Lines", false },
        { "lootFeed", "Display Time", "How long each line stays before it fades.", "Loot Feed", "Lines", false },
        { "lootFeed", "Growth Direction", "The newest line stays at the anchor; older lines stack in this direction.", "Loot Feed", "Lines", false },
        { "lootFeed", "Show Item Value", "What each line is worth, in gold, silver and copper.", "Loot Feed", "Value", false },
        { "lootFeed", "Price Source", "Auction (Naowh Scan) uses your last Scan Prices at the auction house; Auction (TSM) needs TradeSkillMaster. An item without an auction price counts at its vendor price.", "Loot Feed", "Value", false },
        { "lootFeed", "Count Bank Items", "The number on each icon counts your bank as well as your bags.", "Loot Feed", "Value", false },
        { "lootFeed", "Gold per Hour", "A running gold per hour beside the newest line, counting money and item value since your first loot this session.", "Loot Feed", "Value", false },
        { "lootFeed", "Reset Gold per Hour", "Starts the gold per hour count again from your next loot.", "Loot Feed", "Value", false },
        { "lootFeed", "Hide Blizzard Loot Window", "Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full.", "Loot Feed", "Loot Window", false },
        { "lootFeed", "Width", false, "Loot Feed", "Size", false },
        { "lootFeed", "Line Height", "The icon grows and shrinks with it.", "Loot Feed", "Size", false },
        { "lootFeed", "Spacing", "Space between lines. -1 lets neighbouring lines share one border instead of two side by side.", "Loot Feed", "Size", false },
        { "lootFeed", "Font", false, "Loot Feed", "Text", false },
        { "lootFeed", "Font Size", false, "Loot Feed", "Text", false },
        { "lootFeed", "Outline", "A black outline round the text, in place of the soft shadow.", "Loot Feed", "Text", false },
        { "lootFeed", "Style", "A dark or light fill and edge behind each line, or none.", "Loot Feed", "Background", false },
        { "lootFeed", "Glow", "A soft glow beside each icon.", "Loot Feed", "Background", false },
        { "lootTrade", false, "Looting, selling and repairing at vendors, and mail with your alts.", "Looting, Vendors & Mail", false, false },
        { "lootTrade", "Type DELETE For You", "Types DELETE into the confirmation box for you, and names the item in the dialog as a link you can hover for its tooltip.", "Looting, Vendors & Mail", "Looting", false },
        { "lootTrade", "Faster Auto Loot", "Loots automatically without hiding the loot window. Hold Shift to loot manually.", "Looting, Vendors & Mail", "Looting", false },
        { "lootTrade", "Lockpicking Skill", "Lockbox tooltips show the Lockpicking skill needed to open them.", "Looting, Vendors & Mail", "Lockboxes", false },
        { "lootTrade", "Quest Item Info", "Quest item tooltips name the quests they are for and whether each is handed in.", "Looting, Vendors & Mail", "Quest Items", false },
        { "lootTrade", "Quest Reward Sell Price", "Quest reward tooltips show what the item sells to a vendor for.", "Looting, Vendors & Mail", "Quest Rewards", false },
        { "lootTrade", "Auto Repair", "Repairs all gear when you open a vendor who can.", "Looting, Vendors & Mail", "Vendors", false },
        { "lootTrade", "Auto Sell Junk", "Sells grey items when you open a vendor.", "Looting, Vendors & Mail", "Vendors", false },
        { "lootTrade", "Alt Item Counts", "Item tooltips show how many your characters on this realm and faction hold in their bags, bank and mailbox. Each character is counted once you log in on it, and its bank once you open it.", "Looting, Vendors & Mail", "Mail & Alts", false },
        { "lootTrade", "Alts Button on Mail", "An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box.", "Looting, Vendors & Mail", "Mail & Alts", false },
        { "lootTrade", "Quick Attach", "An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click.", "Looting, Vendors & Mail", "Mail & Alts", false },
        { "lootTrade", "Mail Expiry Warning", "At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox.", "Looting, Vendors & Mail", "Mail & Alts", false },
        { "lootTrade", "Forget a Character", "Removes a deleted or transferred character from the counts and the Alts list.", "Looting, Vendors & Mail", "Mail & Alts", false },
        { "auctionPrices", false, "Auction house prices on item tooltips, from your own scans.", "Auction Prices", false, false },
        { "auctionPrices", "Scan Prices Button", "A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes.", "Auction Prices", false, false },
        { "auctionPrices", "Auction House Price", "Item tooltips show an item's auction house price and how old it is.", "Auction Prices", false, false },
        { "auctionPrices", "Waylaid Crate Prices", "Waylaid Crate tooltips show what each filling costs on the auction house.", "Auction Prices", false, false },
        { "auctionPrices", "Craftsman's Writ Prices", "Craftsman's Writ tooltips show the item the writ asks for and what one costs on the auction house.", "Auction Prices", false, false },
        { "auctionPrices", "Sold by Vendors", "Item tooltips say when a vendor sells the item, and what one costs there.", "Auction Prices", false, false },
        { "auctionPrices", "Capture Other Addons' Scans", "Also keeps auction house prices from scans other addons start, such as Auctionator or TSM, full or summary, and from the searches you run and the items you post.", "Auction Prices", false, false },
        { "auctionPrices", "Scan on Opening", "Scans by itself when you open the auction house and your last scan is old.", "Auction Prices", false, false },
        { "auctionPrices", "Scan When Older Than", "How many minutes old your last scan must be to scan on opening.", "Auction Prices", false, false },
        { "auctionPrices", "Prices for Other Addons", "Addons that read Auctionator's prices get these prices while Auctionator is not installed.", "Auction Prices", false, false },
        { "auctionPrices", "TSM Prices", "Tooltips, The Market and Professions use TradeSkillMaster's lowest buyout for an item, and your own scans and Naowh's prices for an item TSM has no price for.", "Auction Prices", false, false },
        { "restock", false, "When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor.", "Restock Reminder", false, false },
        { "restock", "Class Reagents", "The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know.", "Restock Reminder", "Class Reagents", false },
        { "restock", "Buy at Vendors", "At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you.", "Restock Reminder", "Class Reagents", false },
        { "restock", "Ammo", "Restocks equipped thrown weapons, or the arrows or shot in your ammo slot.", "Restock Reminder", "Ammo: Rogue and Warrior", false },
        { "restock", "Ammo to Carry", false, "Restock Reminder", "Ammo: Rogue and Warrior", false },
        { "restock", "Hunter Ammo Reminder", "Reminds you about your equipped ammo at its own amount, not the carry target.", "Restock Reminder", "Ammo: Hunter", false },
        { "restock", "Remind Me When Ammo Falls To", "Reminds at or below this many equipped arrows or shot across all bag stacks.", "Restock Reminder", "Ammo: Hunter", false },
        { "restock", "Food & Drink", "Counts food and drink separately across all stacks. Warriors and rogues do not need drink.", "Restock Reminder", "Food & Drink", false },
        { "restock", "Food & Drink Below", false, "Restock Reminder", "Food & Drink", false },
        { "restock", "Food Minimum Required Level", "Only count food and drink whose required level is within this range.", "Restock Reminder", "Food & Drink", false },
        { "restock", "Food Maximum Required Level", "The same required-level filter applies to every stack, not each item separately.", "Restock Reminder", "Food & Drink", false },
        { "restock", "Junk & Full Bags", "Reminds you to vendor junk, and when your bags are nearly full.", "Restock Reminder", "Bags", false },
        { "restock", "Free Slots Below", false, "Restock Reminder", "Bags", false },
        { "restock", "Font", false, "Restock Reminder", "Text", false },
        { "restock", "Font Size", false, "Restock Reminder", "Text", false },
        { "restock", "Outline", "A black outline round the text, in place of the soft shadow.", "Restock Reminder", "Text", false },
        { "restock", "Background", "A card behind the text, a soft dark fade, or nothing at all.", "Restock Reminder", "Background", false },
        { "gearReminders", false, "An icon while you wear gear you would want to swap out where you are.", "Gear Reminders", false, false },
        { "gearReminders", "Worn Gear Reminder", "An icon while you wear Cloak of Hermitic Bliss in Wailing Caverns, so you remember to swap it.", "Gear Reminders", false, false },
        { "gearReminders", "Fishing Pole Reminder", "An icon while you have a fishing pole equipped, so you remember to swap it.", "Gear Reminders", false, false },
        { "gearReminders", "Fishing Pole Shows In", false, "Gear Reminders", false, false },
        { "gearReminders", "Icon Size", false, "Gear Reminders", false, false },
        { "fishingKey", false, "One key casts Fishing, and the same key reels in your catch.", "One-Key Fishing", false, false },
        { "fishingKey", "Fishing Key", "Press to cast, press again when the bobber splashes.", "One-Key Fishing", false, false },
        { "fishingKey", "Double Right-Click to Cast", "Casts when you double right-click the world with a fishing pole equipped.", "One-Key Fishing", false, false },
        { "fishingKey", "Put On a Lure First", "Puts your best lure on the pole when it has none.", "One-Key Fishing", false, false },
        { "fishingKey", "Put On Fishing Gear First", "Equips your fishing gear first, and combat puts your weapons back.", "One-Key Fishing", false, false },
        { "fishingKey", "Fishing Gear", "A gear set to wear, or just your best fishing pole.", "One-Key Fishing", false, false },
        { "fishingKey", "Put Gear Back", "Puts back what your fishing gear replaced.", "One-Key Fishing", false, false },
        { "fishingSounds", false, "While your line is out, game sounds go up and music and ambience go quiet.", "Louder Splash", false, false },
        { "fishingAutoLoot", false, "Turns auto loot on while your line is out, and off again once your catch is looted.", "Auto Loot While Fishing", false, false },
        { "bagSpace", false, "The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor.", "Bag Space", false, false },
        { "bagSpace", "Items Shown", false, "Bag Space", "Offered", false },
        { "bagSpace", "Highest Quality Offered", "Items above this quality are never offered.", "Bag Space", "Offered", false },
        { "bagSpace", "Grey Items First", "Grey items come before everything else, whatever they sell for.", "Bag Space", "Offered", false },
        { "bagSpace", "Outlevelled Food & Potions First", "Puts food, drink and potions 10 or more levels below you, marked with a clock, first.", "Bag Space", "Offered", false },
        { "bagSpace", "Count Auction Prices", "An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster.", "Bag Space", "Offered", false },
        { "bagSpace", "Protect Needed Items", "Never offers reagents, ammo, quest items, keys, profession tools, enchanting materials, items in an equipment set or items on your BiS list.", "Bag Space", "Offered", false },
        { "bagSpace", "Ignore List", "Items Bag Space never offers. Search for one, drag one in, or middle-click an icon on the row.", "Bag Space", "Offered", false },
        { "bagSpace", "Only With Free Slots Below", "Shows the row only once your bags are this full. 0 shows it all the time.", "Bag Space", "Showing", false },
        { "bagSpace", "Show When Bags Are Full", "An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above.", "Bag Space", "Showing", false },
        { "bagSpace", "Show Free Slots", "Free bag slots out of your total, above the row. Hover it for each bag.", "Bag Space", "Showing", false },
        { "bagSpace", "Count Filled Slots", "Counts the slots you have used instead of the ones still free.", "Bag Space", "Showing", false },
        { "bagSpace", "Slot Count on the Right", "Puts the slot count at the top right of the card, and the Stack button at the left.", "Bag Space", "Showing", false },
        { "bagSpace", "Offer to Stack", "A Stack button on the card when part-filled stacks of an item can be combined.", "Bag Space", "Showing", false },
        { "bagSpace", "Show Prices", "What each stack is worth, in its largest coin, under its icon.", "Bag Space", "Showing", false },
        { "bagSpace", "Pick Up Cheapest Item", "Puts the cheapest item on your cursor, to drop or sell.", "Bag Space", "Showing", false },
        { "bagSpace", "Tooltip: Vendor Price", "What the whole stack sells for at a vendor, and each item's price.", "Bag Space", "Tooltips", false },
        { "bagSpace", "Tooltip: Auction Price", "What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster.", "Bag Space", "Tooltips", false },
        { "bagSpace", "Tooltip: Delete Hint", "The Ctrl-click line, and Click to sell while a vendor is open.", "Bag Space", "Tooltips", false },
        { "bagSpace", "Tooltip: Ignore Hint", "The Middle-click line.", "Bag Space", "Tooltips", false },
        { "bagSpace", "Icon Size", false, "Bag Space", "Size", false },
        { "bagSpace", "Direction", false, "Bag Space", "Size", false },
        { "bagSpace", "Reverse Order", "Puts the cheapest item at the far end of the row instead of next to its anchor.", "Bag Space", "Size", false },
        { "bagSpace", "Larger Cheapest Icon", "Draws the cheapest item's icon a size up, so it stands out from the rest.", "Bag Space", "Size", false },
