        { "anchor", "Growth Direction", "Which way the bar grows from its first button. A column puts the class labels beside the buttons.", "Anchor", false, false },
        { "anchor", "Anchor to an Element", "Opens the HUD Editor: click another Naowh Forever element for the bar to move with.", "Anchor", false, false },
        { "anchor", "Anchor to a Unit Frame", "Attaches the bar to one of your unit frames.", "Anchor", false, false },
        { "anchor", "Unit Frame", "The unit frame the bar is attached to, or UIParent for the screen.", "Anchor", false, false },
        { "anchor", "Bar Point", "The point of the bar that attaches.", "Anchor", false, false },
