    ["Action Bars/Settings"] = {
        { "importing", false, "What a saved set brings back when you import it. Sets are saved and imported from the Bar Sets tab, out of combat. What a saved set brings back when you import it. Sets are saved and imported from the Bar Sets tab, out of combat. /nf bars nf bars /nfbars nfbars save restore import test delete list /nf ab nf ab", "Importing", false, "/nf bars nf bars /nfbars nfbars save restore import test delete list /nf ab nf ab" },
        { "importing", "Highest Rank", "Imports the highest rank you know of each spell instead of the rank that was saved. When off, a rank you no longer have still falls back to your highest.", "Importing", false, false },
        { "importing", "Import Macros", "Makes the set's macros that this character does not have. A macro you already have, by name and text or by text alone, is used as it is: never copied twice or changed.", "Importing", false, false },
        { "importing", "Import Keybinds", "Binds every key the set has bound. Keys the set leaves free keep what they do here.", "Importing", false, false },
        { "importing", "Fill In As You Learn", "A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there.", "Importing", false, false },
        { "importing", "Import on New Character", "For your class: imports this set once on a new character, at level 1 with no experience yet.", "Importing", false, false },
